gws docs documents get --params '{"documentId": "f1980505ad8b4d6e87b1d664537d6aaa"}' 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
text = ''
for item in d['body']['content']:
    if 'paragraph' in item:
        for el in item['paragraph'].get('elements',[]):
            if 'textRun' in el:
                text += el['textRun']['content']
# Find positions of section headers
for line in text.split('\n'):
    idx = text.find(line)
    print(f'{idx+1}: {repr(line)}')
" 2>&1 | grep -E "(Key Decisions|Deadlines|Source Documents|Kickoff|Design Review|Weekly Standup|Sprint 1 Retro|Budget Review|Project Aurora Summary|Compiled)" | head -30

gws docs documents get --params '{"documentId": "f1980505ad8b4d6e87b1d664537d6aaa"}' 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
for item in d['body']['content']:
    if 'paragraph' in item:
        style = item['paragraph'].get('paragraphStyle',{}).get('namedStyleType','')
        text = ''
        for el in item['paragraph'].get('elements',[]):
            if 'textRun' in el:
                text += el['textRun']['content']
        prefix = f'[{style}] ' if style and style != 'NORMAL_TEXT' else ''
        if text.strip():
            print(f'{prefix}{text.rstrip()}')
"
